#ifndef SIM_REPLAY_H
#define SIM_REPLAY_H
// ---------------------------------------------------------------------------
// Hardware-in-the-loop flight replay. Keep this file and sim_replay.c
// byte-identical in both repositories.
//
// The point of this rig is that it does NOT synthesise sensor timing. The
// Training Board still reads its LSM6DSV80X through the hardware FIFO on INT1,
// and Avionics C still waits for the BMP390 to report data-ready; only the
// VALUES they read are replaced, from a table generated by
// tools/make_sim_flight.py out of an Avionics B trajectory. Every FIFO drain,
// SD-write stall and bus conflict therefore stays exactly as real as it is on
// the bench - which is the half of the system a host test cannot reach.
//
// Time. Sim time starts at zero when the board boots and advances one IMU
// sample period per sample the Training Board actually reads, so it tracks real
// sample delivery rather than wall clock. The Training Board stamps its link
// frames with sim time instead of its esp_timer value, which costs nothing on
// the wire (the field is already a sender timestamp) and gives Avionics C an
// exactly aligned index for its own barometer replay - no trigger, no
// handshake, and both boards' logs already record it.
//
// The generated table begins with a stationary pad segment, because the
// trajectory itself starts at ignition and the boards need to settle first:
// Avionics C's estimator is second order with a ~6 s settling time, its pad
// accelerometer bias has to converge, and the high-g channel is armed over the
// first 480 stationary samples.
//
// Enable with -DSIM_REPLAY=1. With it off, none of this is compiled in.
// ---------------------------------------------------------------------------
#include <stdint.h>
#include <stdbool.h>

#ifndef SIM_REPLAY
#define SIM_REPLAY 0
#endif

#if SIM_REPLAY

// Barometric altitude in the table is above the pad; this is the pad's own
// height above sea level, so the pressures handed to the barometer driver look
// like a real site rather than sea level.
#define SIM_PAD_ALTITUDE_M   100.0f

// Where the trajectory's axial acceleration goes. The Training Board's IMU has
// +Y along the airframe toward the nose (confirmed on the boards), and the
// Avionics B trajectories carry the axial component in accZ, so the axial value
// lands on IMU Y and the two lateral components on X and Z.
#define SIM_AXIS_AXIAL       1   // IMU +Y
#define SIM_AXIS_LATERAL_A   0   // IMU X  <- trajectory accX
#define SIM_AXIS_LATERAL_B   2   // IMU Z  <- trajectory accY

// Look up the flight at sim time t_us. Holds the first row before the table
// starts and the last row after it ends, so a run that overshoots simply sits
// on the ground rather than reading off the end.
//   accel_mg   [3], in IMU axis order, already mapped through SIM_AXIS_*
//   gyro_dps   [3], same order
//   alt_m      barometric altitude above the pad
void sim_replay_at(uint32_t t_us, float accel_mg[3], float gyro_dps[3], float *alt_m);

// Barometric pressure in hPa for that altitude, including SIM_PAD_ALTITUDE_M.
float sim_replay_pressure_hpa(float alt_above_pad_m);

// True once sim time has passed the end of the table.
bool sim_replay_finished(uint32_t t_us);

// One line describing the loaded flight, for the boot log.
const char *sim_replay_describe(void);

#endif // SIM_REPLAY
#endif // SIM_REPLAY_H
